import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.charset.StandardCharsets;
public class DES {public static void main(String[]z)throws Exception{Scanner sc=new Scanner(System.in);System.out.print("Enter the text: ");String text=sc.nextLine();System.out.print("Enter 8-character key: ");String key=sc.nextLine();if(key.getBytes(StandardCharsets.UTF_8).length!=8){System.out.println("DES key must be exactly 8 bytes (ASCII characters recommended).");return;}SecretKeySpec sk=new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8),"DES");Cipher c=Cipher.getInstance("DES/CBC/PKCS5Padding");byte[] iv=new byte[8];new java.security.SecureRandom().nextBytes(iv);c.init(Cipher.ENCRYPT_MODE,sk,new IvParameterSpec(iv));byte[] encrypted=c.doFinal(text.getBytes(StandardCharsets.UTF_8));System.out.println("IV (hex): "+hex(iv));System.out.println("Encrypted: "+hex(encrypted));c.init(Cipher.DECRYPT_MODE,sk,new IvParameterSpec(iv));System.out.println("Decrypted: "+new String(c.doFinal(encrypted),StandardCharsets.UTF_8));}static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x));return s.toString();}}
